import itertools

def simulate(N, n_rounds):
    count = 0
    for p in itertools.permutations(range(N)):
        current_guests = list(range(N))
        current_tags = list(p) # guest i has current_tags[i]

        # This is a bit tricky because current_tags needs to be mapped to current_guests.
        # Let's use a dictionary: guest_id -> tag_id
        guest_to_tag = {i: p[i] for i in range(N)}
        guests_present = list(range(N))

        for r in range(n_rounds):
            # 1. Guests with their own name tag exit
            exiting = [g for g in guests_present if guest_to_tag[g] == g]
            for g in exiting:
                guests_present.remove(g)
                del guest_to_tag[g]

            if not guests_present:
                break

            # 2. Pass tags to the right
            # guests_present is already sorted
            m = len(guests_present)
            new_guest_to_tag = {}
            for k in range(m):
                giver = guests_present[k]
                receiver = guests_present[(k + 1) % m]
                new_guest_to_tag[receiver] = guest_to_tag[giver]
            guest_to_tag = new_guest_to_tag

        if guests_present:
            count += 1

    return count

for N in range(2, 6):
    print(f"N={N}, n=4: {simulate(N, 4)}")

